/**
 * Search and filters with a clear button and result count (`design/components/filter-bar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/filter-bar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import { agentMember, claimSlot, elementRef, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/filter-bar.module.css'
import Button from '../controls/Button'
import Inline from '../layout/Inline'

export interface FilterResultCount {
  shown: number
  total?: number
}

export interface FilterBarMessages {
  clear: string
  resultCount: (count: FilterResultCount) => string
}

export interface FilterBarProps {
  /**
   * Filter controls, each an `sm` `Select` with an `emptyOption`.
   */
  children?: JSX.Element
  /**
   * The only input that shows or hides the clear button.
   */
  isFiltered: boolean
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: FilterBarMessages
  onClear: () => void
  resultCount?: FilterResultCount
  /**
   * A `SearchInput`, `sm` by convention.
   */
  search?: JSX.Element
}

/** Search and filters with a clear button and result count. */
export default function FilterBar(given: FilterBarProps): JSX.Element {
  const props = mergeProps(
    {
      messages: (() => ({
        clear: 'Clear filters',
        resultCount: ({ shown, total }: FilterResultCount) =>
          total === undefined ? `${shown} results` : `${shown} of ${total} results`,
      }))(),
    } as Defaults<FilterBarProps, 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const clearRegion = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'FilterBar',
        element: () => root.value,
        state: () => ({
          filtered: props.isFiltered,
          'result-count':
            props.resultCount === undefined ? '' : props.messages.resultCount(props.resultCount),
        }),
        actions: {
          clear: () =>
            (() => {
              if (!props.isFiltered)
                throw new Error('Nothing is filtered, so there is nothing to clear.')
              props.onClear?.()
            })(),
        },
        withholds: () => clearRegion.value,
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <div
        class={styles.bar}
        data-filtered={props.isFiltered ? '' : undefined}
        data-member="filter-bar"
        ref={root.attach}
      >
        <Inline gap={3} align="center" wrap={true}>
          {props.search}
          {props.children}
          {props.isFiltered ? (
            <span class={styles.clear} ref={clearRegion.attach}>
              <Button
                variant="ghost"
                tone="neutral"
                size="sm"
                icon="clear"
                label={props.messages.clear}
                onClick={() => props.onClear?.()}
              />
            </span>
          ) : null}
          {props.resultCount !== undefined ? (
            <span class={styles.count} aria-live="polite">
              {props.messages.resultCount(props.resultCount)}
            </span>
          ) : null}
        </Inline>
      </div>
    )
  })
}
